#include <iostream>
#include <vector>

// Function to find quadruplets that sum up to a target value
void printQuad(std::vector<int> vec, int target) {
    std::sort(vec.begin(), vec.end());
    for (int i = 0; i < vec.size() - 3; ++i) {
        if (i > 0 && vec[i] == vec[i-1]) continue;
        for (int j = i + 1; j < vec.size() - 2; ++j) {
            if (j > i+1 && vec[j] == vec[j-1]) continue;
            int left = j+1, right = vec.size()-1;
            while(left < right) {
                int sum = vec[i]+vec[j]+vec[left]+vec[right];
                if(sum == target) {
                    std::cout << "[";
                    for(int k=0; k<4; ++k) {
                        std::cout << vec[(k==0)? i : (k==1)? j : (k==2)? left : right] << ", ";
                    }
                    std::cout << "]" << std::endl;
                    left++;
                    right--;
                } else if(sum < target) left++;
                else right--;
            }
        }
    }
}

int main() {
    std::vector<int> vec = {4, 1, 2, -1, 1, -3};
    int target = 1;
    printQuad(vec, target);
    return 0;
}
